  %% ===== PARAMETERS - these macros DRIVE the drawing =====
  %% Change one and the picture changes; that is what makes
  %% encoding.geometric_constraints a real check rather than a comment.
  \pgfmathsetmacro{\Ra}{2.3}                 % pitch radius, driving wheel A
  \pgfmathtruncatemacro{\NA}{24}             % teeth on A
  \pgfmathtruncatemacro{\NB}{13}             % teeth on B
  \pgfmathsetmacro{\Rb}{\Ra*\NB/\NA}         % equal module is what lets them mesh
  \pgfmathsetmacro{\Cdist}{\Ra+\Rb}          % pitch circles tangent
  \pgfmathsetmacro{\Modu}{2*\Ra/\NA}         % module m = 2R/N, shared
  \pgfmathsetmacro{\RtA}{\Ra+0.9*\Modu}      % addendum 0.9m
  \pgfmathsetmacro{\RrA}{\Ra-1.15*\Modu}     % dedendum 1.15m -> clearance 0.25m
  \pgfmathsetmacro{\RtB}{\Rb+0.9*\Modu}
  \pgfmathsetmacro{\RrB}{\Rb-1.15*\Modu}
  \pgfmathsetmacro{\PitchA}{360/\NA}
  \pgfmathsetmacro{\PitchB}{360/\NB}
  \pgfmathsetmacro{\TipHA}{0.17*\PitchA}     % tooth half-width at the tip
  \pgfmathsetmacro{\RootHA}{0.30*\PitchA}    % and at the root
  \pgfmathsetmacro{\TipHB}{0.17*\PitchB}
  \pgfmathsetmacro{\RootHB}{0.30*\PitchB}
  \pgfmathtruncatemacro{\NAlast}{\NA-1}
  \pgfmathtruncatemacro{\NBlast}{\NB-1}
  %% B is phased half a pitch off the line of centres, so a GAP on B faces the
  %% tooth A presents at 0 deg. Without this the two wheels interpenetrate.
  \pgfmathsetmacro{\PhaseB}{180+\PitchB/2}
  \pgfmathsetmacro{\aL}{2.92}                % lever panel, arm a
  \pgfmathsetmacro{\bL}{\aL*\Rb/\Ra}         % same a:b ordering as the gear panel
  %% ---------------- upper panel: two overlapping levers ----------------
  \begin{scope}[yshift=1.05cm]
    \draw (0,-0.10) -- (\aL+0.55,-0.10) -- (\aL+0.55,0.10) -- (0,0.10);
    \draw (0,-0.10) arc (-90:90:0.30 and 0.10);
    \fill (0,0) circle (0.055); \draw (0,0) circle (0.078);
    \draw (\aL,0.34) -- (\aL+\bL+0.85,0.34) (\aL,0.54) -- (\aL+\bL+0.85,0.54);
    \draw (\aL,0.34) -- (\aL,0.54);
