  \def\XR{3.2}     % where the hump starts to rise
  \def\XCa{4.3}    % left end of the flat crest
  \def\XCb{5.6}    % right end of the flat crest = the take-off point
  \def\HTOP{1.15}  % drawn height of the crest above the approach ground
  \def\XE{10.4}    % right-hand end of the landing slope
  \def\ALPHA{25}   % slope angle to the horizontal, as labelled
  \def\XD{8.9}     % right end of the dashed horizontal reference line
  \def\XM{5.05}    % x at which the height h is dimensioned
  \pgfmathsetmacro{\YE}{\HTOP-(\XE-\XCb)*tan(\ALPHA)}
  \def\CA{0.70}
  % ---- snow surface: flat approach, S-shaped rise, flat crest, straight slope
  \draw[line width=1.1pt]
    (\XL,\GY) -- (\XR,\GY)
      .. controls (\XR+\CA,\GY) and (\XCa-\CA,\HTOP) .. (\XCa,\HTOP)
    -- (\XCb,\HTOP) -- (\XE,\YE);
  % ---- hatching under the flat approach
  \foreach \x in {0.12,0.42,...,3.15}{\draw[line width=0.4pt] (\x,\GY) -- ++(-0.20,-0.30);}
  % ---- hatching under the rise, points taken on the actual Bezier
  \foreach \s in {0.18,0.36,0.54,0.72,0.90}{%
    \pgfmathsetmacro{\xx}{(1-\s)*(1-\s)*(1-\s)*\XR + 3*(1-\s)*(1-\s)*\s*(\XR+\CA)
                          + 3*(1-\s)*\s*\s*(\XCa-\CA) + \s*\s*\s*\XCa}%
    \pgfmathsetmacro{\yy}{3*(1-\s)*\s*\s*\HTOP + \s*\s*\s*\HTOP}%
    \draw[line width=0.4pt] (\xx,\yy) -- ++(-0.20,-0.30);}
  % ---- hatching under the flat crest
  \foreach \i in {0,...,4}{%
