\begin{tikzpicture}[line width=0.7pt]
  % The wedge is built from the apex position (PX,PY) and the base length; the two
  % face angles THA, THB are then COMPUTED from that geometry, and the same computed
  % values drive both the rotated block/string frames and the drawn angle arcs. A
  % label can therefore never point at an angle the drawing does not contain.
  \def\BASE{9.0}\def\PX{2.40}\def\PY{3.40}
  \def\PR{0.17}\def\SA{1.75}\def\SB{2.60}\def\BW{0.85}\def\BH{0.55}
  \pgfmathsetmacro{\THA}{atan(\PY/\PX)}
  \pgfmathsetmacro{\THB}{atan(\PY/(\BASE-\PX))}
  \pgfmathsetmacro{\LA}{sqrt(\PX*\PX+\PY*\PY)}
  \pgfmathsetmacro{\LB}{sqrt((\BASE-\PX)*(\BASE-\PX)+\PY*\PY)}
  \coordinate (A) at (0,0);
  \coordinate (B) at (\BASE,0);
  \coordinate (P) at (\PX,\PY);
  % the wedge itself
  \draw (A) -- (B) -- (P) -- cycle;
  % pulley at the apex
  \draw[fill=white] (P) circle (\PR);
  \fill (P) circle (0.05);
  % left face: block m, and the string run PARALLEL to that face
  \begin{scope}[shift={(A)},rotate=\THA]
    \draw (\SA,0) rectangle ++(\BW,\BH);
    \draw (\SA+\BW,\PR) -- (\LA,\PR);
    \node[left,inner sep=4pt] at (\SA,\BH) {\small$m$};
  \end{scope}
  % right face: block M, and its string run, also parallel to its face
  \begin{scope}[shift={(P)},rotate=-\THB]
    \draw (\SB,0) rectangle ++(\BW,\BH);
    \draw (0,\PR) -- (\SB,\PR);
    \node[above right,inner sep=2pt] at (\SB+\BW/2,\BH) {\small$M$};
  \end{scope}
  % angle arcs, drawn from the SAME computed angles
